    def _validate_identity_fields(self) -> "ActorContext":
        if self.id != self.actor_id:
            raise ValueError("ActorContext.id must match ActorContext.actor_id")
        return self

    @classmethod
    def create(
        cls,
        *,
        actor_id: str,
        issuer: str,
        subject: str,
        username: str,
        display_name: str,
        auth_type: str,
        active: bool,
        permissions: tuple[str, ...],
        group_refs: tuple[str, ...],
    ) -> "ActorContext":
