from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from typing import Any, Iterable, Mapping
from uuid import uuid4

from fastapi import Depends, HTTPException, Request, status

from backend.shared.contracts.actor_contracts import ActorContext

logger = logging.getLogger(__name__)

SENSITIVE_AUTH_KEYS = frozenset(
    {
        "access_token",
        "authorization",
        "assertion",
        "bearer",
        "id_token",
        "refresh_token",
        "saml_assertion",
        "token",
    }
)

SAML_ROLE_KEYS = (
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/role",
    "http://schemas.xmlsoap.org/claims/group",
)
SAML_SUBJECT_KEYS = (
    "nameid",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
)
USERNAME_KEYS = ("preferred_username", "upn", "email", "username")
DISPLAY_NAME_KEYS = ("name", "display_name")
ACTIVE_KEYS = ("active", "is_active", "enabled", "account_enabled")


def _normalize_token(value: Any) -> str:
    return str(value).strip().lower()


def _iter_values(value: Any) -> Iterable[str]:
    if value is None:
        return ()
    if isinstance(value, str):
        return (value,)
    if isinstance(value, (list, tuple, set, frozenset)):
        return tuple(str(item) for item in value)
    return (str(value),)


def _iter_scope_values(value: Any) -> Iterable[str]:
    if value is None:
        return ()
    if isinstance(value, str):
        return tuple(part for part in value.split() if part.strip())
    return _iter_values(value)


def _first_non_empty(claims: Mapping[str, Any], *keys: str) -> str | None:
    for key in keys:
        value = claims.get(key)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return None


def _first_present(claims: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in claims:
            return claims[key]
    return None


def _normalize_active(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    token = str(value).strip().lower()
    if token in {"false", "0", "no", "n", "inactive", "disabled"}:
        return False
    if token in {"true", "1", "yes", "y", "active", "enabled"}:
        return True
    return True


def _looks_like_permission(token: str) -> bool:
    return ":" in token or "." in token


def redact_auth_payload(value: Any) -> Any:
    if isinstance(value, Mapping):
        redacted: dict[str, Any] = {}
        for key, item in value.items():
            if _normalize_token(key) in SENSITIVE_AUTH_KEYS:
                redacted[str(key)] = "[REDACTED]"
            else:
                redacted[str(key)] = redact_auth_payload(item)
        return redacted
    if isinstance(value, list):
        return [redact_auth_payload(item) for item in value]
    if isinstance(value, tuple):
        return tuple(redact_auth_payload(item) for item in value)
    if isinstance(value, str) and value.lower().startswith("bearer "):
        return "Bearer [REDACTED]"
    return value


def _has_sensitive_auth_fields(value: Any) -> bool:
    if isinstance(value, Mapping):
        for key, item in value.items():
            if _normalize_token(key) in SENSITIVE_AUTH_KEYS:
                return True
            if _has_sensitive_auth_fields(item):
                return True
        return False
    if isinstance(value, (list, tuple, set, frozenset)):
        return any(_has_sensitive_auth_fields(item) for item in value)
    if isinstance(value, str):
        return value.lower().startswith("bearer ")
    return False


def _emit_structured_log(event: str, **fields: object) -> None:
    logger.info(json.dumps({"event": event, **fields}, sort_keys=True))


def get_request_id(request: Request) -> str:
    existing = getattr(request.state, "request_id", None)
    if existing:
        return str(existing)

    incoming = request.headers.get("x-request-id")
    request_id = incoming.strip() if incoming and incoming.strip() else str(uuid4())
    request.state.request_id = request_id
    return request_id


def _authentication_error(
    request: Request,
    *,
    reason: str,
    detail: str,
) -> HTTPException:
    _emit_structured_log(
        "auth.request.denied",
        request_id=get_request_id(request),
        outcome="unauthorized",
        reason=reason,
    )
    return HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail=detail,
    )


def _authorization_error(
    request: Request,
    *,
    actor_id: str,
    reason: str,
) -> HTTPException:
    _emit_structured_log(
        "auth.request.denied",
        request_id=get_request_id(request),
        actor_id=actor_id,
        outcome="forbidden",
        reason=reason,
    )
    return HTTPException(
        status_code=status.HTTP_403_FORBIDDEN,
        detail="Forbidden.",
    )


@dataclass(slots=True)
class AuthPolicy:
    permission_map: Mapping[str, set[str]] = field(
        default_factory=lambda: {
            "reviewers": {"document.read"},
            "writers": {"document.read", "document.write"},
            "auditors": {"audit.read"},
        }
    )

    def normalize_actor(
        self,
        claims: Mapping[str, Any],
        *,
        auth_type: str,
        request_id: str = "n/a",
    ) -> ActorContext:
        issuer = _first_non_empty(claims, "iss", "issuer", "saml_issuer") or "unknown-issuer"
        subject = _first_non_empty(claims, "sub", *SAML_SUBJECT_KEYS, "uid")
        username = _first_non_empty(claims, *USERNAME_KEYS) or subject
        display_name = _first_non_empty(claims, *DISPLAY_NAME_KEYS)
        active = _normalize_active(_first_present(claims, *ACTIVE_KEYS))

        if not username and not subject:
            _emit_structured_log(
                "auth.request.denied",
                request_id=request_id,
                outcome="unauthorized",
                reason="missing_identity",
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Authentication required.",
            )

        resolved_subject = subject or username or "anonymous"
        resolved_username = username or resolved_subject
        resolved_display_name = display_name or resolved_username

        group_refs = self._group_refs(claims)
        permissions = self._permissions(claims, group_refs)
        actor_id = f"{issuer}:{resolved_subject}"

        _emit_structured_log(
            "auth.actor.normalized",
            request_id=request_id,
            actor_id=actor_id,
            auth_type=auth_type,
            active=active,
            permission_count=len(permissions),
            claims_redacted=_has_sensitive_auth_fields(claims),
        )

        return ActorContext.create(
            actor_id=actor_id,
            issuer=issuer,
            subject=resolved_subject,
            username=resolved_username,
            display_name=resolved_display_name,
            auth_type=auth_type,
            active=active,
            permissions=tuple(sorted(permissions)),
            group_refs=tuple(sorted(group_refs)),
        )

    def require_permission(
        self,
        actor: ActorContext,
        permission: str,
        *,
        request: Request,
    ) -> ActorContext:
        if not actor.active:
            raise _authorization_error(
                request,
                actor_id=actor.actor_id,
                reason="inactive_actor",
            )
        if permission not in actor.permissions:
            raise _authorization_error(
                request,
                actor_id=actor.actor_id,
                reason="missing_permission",
            )
        return actor

    def _group_refs(self, claims: Mapping[str, Any]) -> set[str]:
        refs: set[str] = set()
        for key in ("groups", "roles", "role", *SAML_ROLE_KEYS):
            for value in _iter_values(claims.get(key)):
                token = _normalize_token(value)
                if token:
                    refs.add(token)
        return refs

    def _permissions(self, claims: Mapping[str, Any], group_refs: set[str]) -> set[str]:
        permissions: set[str] = set()

        for ref in group_refs:
            permissions.update(self.permission_map.get(ref, set()))

        for key in ("permissions", "permission"):
            for value in _iter_values(claims.get(key)):
                token = _normalize_token(value)
                if not token:
                    continue
                permissions.update(self.permission_map.get(token, set()))
                if _looks_like_permission(token):
                    permissions.add(token)

        for key in ("scope", "scp"):
            for value in _iter_scope_values(claims.get(key)):
                token = _normalize_token(value)
                if not token:
                    continue
                permissions.update(self.permission_map.get(token, set()))
                if _looks_like_permission(token):
                    permissions.add(token)

        return permissions


def get_auth_policy(request: Request) -> AuthPolicy:
    return getattr(request.app.state, "auth_policy", AuthPolicy())


def _resolve_auth_type(request: Request, claims: Mapping[str, Any]) -> str:
    explicit = request.headers.get("x-auth-provider")
    if explicit:
        return explicit.strip().lower()
    if any(key in claims for key in SAML_SUBJECT_KEYS + SAML_ROLE_KEYS):
        return "saml"
    return "oidc"


def _claims_from_request(request: Request) -> Mapping[str, Any]:
    raw_claims = request.headers.get("x-auth-claims")
    if not raw_claims:
        raise _authentication_error(
            request,
            reason="missing_claims",
            detail="Authentication required.",
        )

    try:
        parsed = json.loads(raw_claims)
    except json.JSONDecodeError as exc:
        raise _authentication_error(
            request,
            reason="invalid_claims_json",
            detail="Invalid authentication context.",
        ) from exc

    if not isinstance(parsed, dict):
        raise _authentication_error(
            request,
            reason="invalid_claims_shape",
            detail="Invalid authentication context.",
        )

    return parsed


def get_actor_context(
    request: Request,
    policy: AuthPolicy = Depends(get_auth_policy),
) -> ActorContext:
    claims = _claims_from_request(request)
    return policy.normalize_actor(
        claims,
        auth_type=_resolve_auth_type(request, claims),
        request_id=get_request_id(request),
    )


def require_permission(permission: str):
    def dependency(
        request: Request,
        actor: ActorContext = Depends(get_actor_context),
        policy: AuthPolicy = Depends(get_auth_policy),
    ) -> ActorContext:
        return policy.require_permission(actor, permission, request=request)

    return dependency
